import {fresh,status,weak,past,queue,mockQueue,rate,readProgress,saveProgress,parseProgress,normalize,filterQuestions,KEY} from './core.js';
import {guideConfig,sendGuideMessage} from './guide-client.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db,p,storage,storageOk=true,reviewFilter='weak',filters={courses:[],mode:'mixed',count:20},timer,chat=[],chatContext={},searchTimer;
const app=$('#app'),modal=$('#overlay');
const icons=['φ','Aa','≃','ə','[ ]','ψ','↗'],tints=['#eee9f5','#e8eee3','#f4e9db','#e8edf6','#eee9e3','#f3e7e8','#e5eeee'];
const qBy=new Map(),tBy=new Map(),cBy=new Map();
const button=(label,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const title=(eyebrow,heading,sub='',aside='')=>`<div class="heading"><div><div class="eyebrow">${eyebrow}</div><h1>${heading}</h1>${sub?`<p>${sub}</p>`:''}</div>${aside}</div>`;
function toast(text){const el=$('#toast');el.textContent=text;el.style.display='block';clearTimeout(el.hide);el.hide=setTimeout(()=>el.style.display='none',3500);}
function persist(){if(!saveProgress(storage,p)){storageOk=false;const n=$('#storage-notice');if(n)n.hidden=false;}}
function record(id){return p.questions[id]??={attempts:[],note:'',bookmarked:false};}
function sources(refs){return `<div class="sources"><strong>Source notes</strong>${(refs||[]).map(r=>{const s=db.sources.find(s=>s.id===r.id);return s?`<span>${s.kind==='web'?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>`:esc(s.title)+(r.pages?.length?' · PDF '+(r.pages.length>1?'pages ':'page ')+r.pages.join(', '):'')}</span>`:'';}).join('')}</div>`;}
function shell(section,html){const nav=[['home','⌂','Home'],['study','▤','Study'],['practice','◇','Practice'],['review','↺','Review']];app.innerHTML=`<aside class="sidebar"><a class="brand" href="#home"><span class="brand-mark">v.</span> Viva Studio</a><div class="brand-sub">YOUR WORDS. YOUR CONFIDENCE.</div><nav class="nav" aria-label="Main navigation">${nav.map(([id,ic,n])=>`<a href="#${id}" ${id===section?'class="active" aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${ic}</span>${n}</a>`).join('')}</nav><div class="sidebar-foot"><div class="leaf">∿</div><p>A little clarity,<br>every question.</p><small>English · Final year<br>Jahangirnagar University</small><p style="margin-top:22px"><a href="#coverage">Content & sources ↗</a></p></div></aside><div class="shell"><header class="topbar"><a class="brand mobile-brand" href="#home"><span class="brand-mark">v.</span> Viva Studio</a><div class="breadcrumb">Your study space <span style="margin:0 12px">/</span> ${section[0].toUpperCase()+section.slice(1)}</div><div class="top-actions"><button class="top-search" data-action="search" aria-label="Search the study guide">⌕ <span class="search-label">Find a concept</span><span class="key">/</span></button><button class="guide-btn" data-action="guide">✧ Ask Guide</button></div></header><main class="content" id="main" tabindex="-1"><div class="notice" id="storage-notice" ${storageOk?'hidden':''}>Your browser could not save progress. You can still study; export your progress before leaving.</div>${html}</main></div>`;}
function courseCard(c,i){const qs=db.questions.filter(q=>q.courseIds.length===1&&q.courseIds[0]===c.id),done=qs.filter(q=>status(p,q.id)!=='unseen').length;return `<a class="course-card" href="#study/${c.id}" style="--tint:${tints[i%7]}"><div class="course-top"><span class="course-icon">${icons[i%7]}</span><span class="pill">${c.id}</span></div><h3>${esc(c.title)}</h3><p>${c.topics.length} focused topics · ${qs.length} questions</p><progress value="${done}" max="${qs.length}" aria-label="${esc(c.title)} attempted"></progress><div class="course-meta"><span>${done?`${done} explored`:'Ready when you are'}</span><span>Open course ↗</span></div></a>`;}
function home(){const all=db.questions,attempted=all.filter(q=>status(p,q.id)!=='unseen').length,got=all.filter(q=>status(p,q.id)==='got').length,needs=all.filter(q=>weak(p,q.id)).length,es=all.filter(q=>q.essential),esdone=es.filter(q=>status(p,q.id)!=='unseen').length;const active=p.session?.state==='active',last=tBy.get(p.lastTopic);shell('home',title('YOUR VIVA, ONE STEP AT A TIME','Make room for clarity.','Understand the idea. Find your words. Practise with purpose.',`<span class="pill">● &nbsp; 7 courses · One study space</span>`)+`<section class="hero"><div class="hero-copy"><div class="eyebrow">THE TWO-DAY PATH</div><h2>Small questions.<br>A stronger understanding.</h2><p>Your ${es.length} essentials connect the foundations across all seven courses. Start here, then follow what needs a little more practice.</p>${button(active?'Continue your session →':'Practise the essentials →',active?'resume':'essentials','lime')} <a href="#study" class="text-link" style="color:#d6e3c2;margin-left:12px">Explore the guides</a></div><div class="hero-art" aria-hidden="true"><div class="orbit"><span class="orbit-label">UNDERSTAND</span><b>v.</b><span class="orbit-label">SAY IT OUT LOUD</span></div></div></section>${last?`<div class="notice" style="background:#edf1e7"><a href="#study/${last.courseId}/${last.id}">Continue reading: <strong>${esc(last.title)}</strong> →</a></div>`:""}<div class="stats"><div class="stat"><b>${esdone}<small> / ${es.length}</small></b><span>Essentials explored</span></div><div class="stat"><b>${attempted}</b><span>Questions attempted</span></div><div class="stat"><b>${got}</b><span>Self-rated “Got it”</span></div><div class="stat"><b>${needs}</b><span>Need another look</span></div></div><div class="section-head"><h2>Your seven courses</h2><a href="#study">Explore all courses ↗</a></div><div class="grid">${db.courses.map(courseCard).join('')}</div><div class="bottom-grid"><section class="card"><div class="eyebrow">A SIMPLE ROUTE THROUGH IT ALL</div><h2>Your preparation path</h2><div class="path-step"><span class="number">1</span><div><h3>Build your foundation</h3><p>Course overviews + the ${es.length} essentials</p></div><a href="#study">↗</a></div><div class="path-step"><span class="number">2</span><div><h3>Connect the ideas</h3><p>Applications, comparisons and cross-course questions</p></div><button class="text-link" data-action="connections">Explore ↗</button></div><div class="path-step"><span class="number">3</span><div><h3>Put it into words</h3><p>Revisit weak areas, then try a timed viva</p></div><button class="text-link" data-action="mock">Try it ↗</button></div></section><section class="card quote"><div class="eyebrow">A NOTE BEFORE YOU BEGIN</div><h2>Clarity comes before<br>perfect wording.</h2><p>Say what the concept means. Give one useful example. Add a distinction when it helps. You are practising understanding, not memorising a script.</p><div class="button-row"><a class="btn ghost" href="#review">Review your progress ↗</a></div></section></div>`);}
function study(courseId,topicId){const c=cBy.get(courseId);if(!c){shell('study',title('UNDERSTAND BEFORE YOU REHEARSE','The study library.','Short explanations, useful examples, and the connections that make ideas stick.')+`<div class="grid">${db.courses.map(courseCard).join('')}</div>`);return;}const t=tBy.get(topicId);if(t&&t.courseId!==c.id){location.hash=`study/${c.id}`;return;}if(t){p.lastTopic=t.id;persist();}const nav=`<aside class="topic-nav"><a href="#study/${c.id}" ${!t?'class="active"':''}>The course in one view</a>${c.groups.map(g=>`<h3>${esc(g.title)}</h3>${c.topics.filter(t=>t.groupId===g.id).map(t=>`<a href="#study/${c.id}/${t.id}" ${t.id===topicId?'class="active"':''}>${esc(t.title)}</a>`).join('')}`).join('')}</aside>`;let body;if(t){body=`<article class="card lesson"><div class="eyebrow">${c.id} · ${esc(c.shortTitle)}</div><h1>${esc(t.title)}</h1><div class="core">${esc(t.core)}</div><h3>Say it in the viva</h3><p>${esc(t.questions[0]?.answer||t.core)}</p><div class="example"><h3>A concrete example</h3><p>${esc(t.example)}</p></div><details open><summary>Understand more</summary><p>${esc(t.explanation)}</p></details><div class="callout"><strong>Keep this distinction clear</strong><p>${esc(t.confusion)}</p></div>${t.diagram?`<pre class="tree">${esc(t.diagram)}</pre>`:''}<div class="button-row">${button('Practise this topic →','topic-practice','primary',`data-id="${t.id}"`)}${button('Ask about this','topic-guide','',`data-id="${t.id}"`)}</div>${t.related?.length?`<h3>Connected ideas</h3><div class="inline-badges">${t.related.filter(id=>tBy.has(id)).map(id=>{let r=tBy.get(id);return `<a class="pill" href="#study/${r.courseId}/${id}">${esc(r.title)} ↗</a>`;}).join('')}</div>`:''}${sources(t.sources)}</article>`;}else{body=`<article class="card lesson"><div class="eyebrow">${c.id} · THE COURSE IN ONE VIEW</div><h1>${esc(c.title)}</h1><div class="core">${esc(c.overview)}</div><h3>Follow the idea</h3>${c.journey.map((s,i)=>`<div class="path-step"><span class="number">${i+1}</span><p>${esc(s)}</p></div>`).join('')}<div class="button-row">${button('Practise this course →','course-practice','primary',`data-id="${c.id}"`)}${button('20 essentials','course-essentials','',`data-id="${c.id}"`)}</div><h3>Start with a topic</h3><div class="question-list">${c.groups.map(g=>`<a class="question-row" href="#study/${c.id}/${c.topics.find(t=>t.groupId===g.id)?.id}"><strong>${esc(g.title)}</strong><p class="muted">${esc(g.syllabus.join(' · '))}</p></a>`).join('')}</div></article>`;}shell('study',`<div class="section-head" style="margin-top:0"><a href="#study">← All courses</a><span class="pill">${c.topics.length} topics</span></div><div class="study-layout">${nav}${body}</div>`);}
function setup(){const count=filterQuestions(db.questions,filters,p).length;const opts=(values,current)=>values.map(([v,l])=>`<option value="${v}" ${v===current?'selected':''}>${l}</option>`).join('');shell('practice',title('ACTIVE RECALL, AT YOUR PACE','Find your words.','Answer out loud or make a quick note. Reveal the answer, then decide what needs another try.')+`<div class="tabs">${[['mixed','Mixed practice'],['drill','Course drill'],['connections','Connections'],['mock','Mock viva'],['all','Full question bank']].map(([m,l])=>button(l,'mode',filters.mode===m?'active':'',`data-mode="${m}"`)).join('')}</div><div class="setup"><section class="card"><h2>${filters.mode==='mock'?'Set the scene':'Make it your session'}</h2><p class="muted" style="font-size:12px;margin-top:10px">${filters.mode==='mock'?'Answers stay hidden until the viva ends. Follow-up questions are prepared in advance.':'Choose your courses and focus. No answer options, no pressure to type.'}</p><div class="section-head"><h3>Courses</h3><button class="text-link" data-action="all-courses">Select all</button></div><div class="checks">${db.courses.map(c=>`<label class="check"><input type="checkbox" name="course" value="${c.id}" ${!filters.courses.length||filters.courses.includes(c.id)?'checked':''}>${c.id} · ${esc(c.shortTitle)}</label>`).join('')}</div><div class="fields"><label class="field">Difficulty<select data-filter="difficulty">${opts([['','All levels'],['foundation','Foundation'],['applied','Applied'],['challenge','Challenge']],filters.difficulty||'')}</select></label><label class="field">Question type<select data-filter="type">${opts([['','All types'],...['definition','identification','contribution','distinction','example','explanation','application','criticism','connection'].map(x=>[x,x[0].toUpperCase()+x.slice(1)])],filters.type||'')}</select></label><label class="field">Topic<select data-filter="topic">${opts([['','All topics'],...db.topics.filter(t=>!filters.courses.length||filters.courses.includes(t.courseId)).map(t=>[t.id,`${t.courseId} · ${t.title}`])],filters.topic||'')}</select></label><label class="field">Focus<select data-filter="status">${opts([['','Any progress'],['unseen','Not tried yet'],['weak','Needs practice'],['past','Past mistakes'],['bookmarked','Bookmarked']],filters.status||'')}</select></label><label class="field">${filters.mode==='mock'?'Time limit':'Session length'}<select data-filter="${filters.mode==='mock'?'minutes':'count'}">${opts((filters.mode==='mock'?[8,10]:[10,20,30,790]).map(n=>[String(n),n===790?'All matching questions':n+(filters.mode==='mock'?' minutes':' questions')]),String(filters.mode==='mock'?(filters.minutes||10):filters.count))}</select></label><label class="check" style="align-self:center"><input type="checkbox" data-filter="essential" ${filters.essential?'checked':''}>Essentials only</label></div><div class="button-row">${button(filters.mode==='mock'?'Begin mock viva →':'Start practising →','start','primary',count?'':'disabled')}<span class="count-label" style="align-self:center">${count} matching questions</span></div>${!count?'<p class="muted">Try broadening a filter to find more questions.</p>':''}</section><aside><section class="card quote"><div class="eyebrow">HOW TO USE THIS SPACE</div><h2>Think. Say it.<br>Check. Repeat.</h2><p>One clear idea is a good start. After revealing the answer, compare the key points—not the exact wording.</p><div class="path-step"><span class="number">✓</span><div><h3>Got it</h3><p>The main idea and key distinction are there.</p></div></div><div class="path-step"><span class="number">~</span><div><h3>Partly</h3><p>You have the idea, with something to refine.</p></div></div><div class="path-step"><span class="number">↺</span><div><h3>Missed</h3><p>A useful cue for your next practice.</p></div></div></section>${p.session?.state==='active'?`<section class="card" style="margin-top:15px"><h3>You have an unfinished session</h3><p class="muted">Starting a new one replaces that session. Your ratings and notes stay saved.</p><div class="button-row">${button('Resume →','resume')}</div></section>`:''}</aside></div>`);}
function answerHTML(q){const t=tBy.get(q.topicIds[0]);return `<section class="answer"><div class="eyebrow">THE SHORT ANSWER</div><p class="direct">${esc(q.shortAnswer)}</p><h3>A viva-ready answer</h3><p style="margin-top:10px">${esc(q.answer)}</p><h3 style="margin-top:20px">Listen for these points</h3><ul>${q.keyPoints.map(k=>`<li>${esc(k)}</li>`).join('')}</ul><details><summary>Understand the reasoning</summary><p>${esc(q.explanation||t?.explanation||q.answer)}</p>${q.example||t?.example?`<p><strong>Example:</strong> ${esc(q.example||t.example)}</p>`:''}</details>${sources(q.sources)}</section>`;}
function ratingHTML(q,s,slot){return `<div class="rating" role="group" aria-label="Self-assess your answer">${[['missed','↺ Missed'],['partly','~ Partly'],['got','✓ Got it']].map(([v,l])=>`<button data-action="rate" data-id="${q.id}" data-rating="${v}" class="${slot.rating===v?'selected':''}" aria-pressed="${slot.rating===v}">${l}</button>`).join('')}</div><small>Your assessment is saved on this browser.</small>`;}
function session(){const s=p.session;if(!s){location.hash='practice';return;}if(s.kind==='mock'&&s.state==='active'&&Date.now()>=s.deadline){finish();return;}if(s.state==='complete'){results();return;}const id=s.ids[s.index],q=qBy.get(id);if(!q){finish();return;}const slot=s.answers[id]??={};const mock=s.kind==='mock';shell('practice',`<div class="session-wrap"><div class="session-top"><a href="#practice">← Session settings</a>${mock?'<span class="timer" id="timer" aria-label="Time remaining"></span>':`<span class="muted">Question ${s.index+1} of ${s.ids.length}</span>`}${button('Finish','finish','small')}</div><progress value="${s.index}" max="${s.ids.length}" aria-label="Session progress"></progress><article class="card question-card"><div class="inline-badges"><span class="pill">${q.courseIds.join(' + ')}</span><span class="pill">${esc(q.difficulty)}</span><span class="pill orange">${esc(q.type)}</span></div><h2>${esc(q.prompt)}</h2><p class="muted" style="font-size:12px">Take a moment. Answer out loud, in your head, or in a short note.</p><label class="field" style="margin-top:20px">Your note <span class="muted">(optional)</span><textarea id="answer-note" data-qid="${q.id}" placeholder="A few words to hold your thought…">${esc(record(id).note)}</textarea></label><div class="button-row">${button(record(id).bookmarked?'★ Saved':'☆ Save question','bookmark','small',`data-id="${id}"`)}${!mock?button('Ask about this','question-guide','small',`data-id="${id}"`):''}</div>${!mock&&slot.shown?answerHTML(q)+ratingHTML(q,s,slot):''}<div class="button-row">${mock?button('Next question →','next','primary'):slot.shown?button('Next question →','next','primary'):button('Show answer','reveal','primary')}${!mock&&!slot.shown?button('I don’t know','dontknow'):''}${!mock&&s.index>0?button('← Previous','previous','ghost'):''}${button('Skip','skip','ghost')}</div></article><p class="muted" style="font-size:11px;text-align:center;margin-top:18px">${mock?'Answers are hidden until the end. The timer continues if you leave this page.':'No word-for-word scoring. You decide whether the important ideas are there.'}</p></div>`);if(mock)tick();}
function results(){const s=p.session,ids=s.ids,attempted=ids.filter(id=>s.answers[id]?.rating),missed=attempted.filter(id=>['missed','partly'].includes(s.answers[id].rating));shell('practice',title(s.kind==='mock'?'MOCK VIVA · REFLECTION':'SESSION COMPLETE','A little clearer than before.',s.kind==='mock'?'Review the questions you reached, reveal each answer, and assess your understanding.':'Your next step is already here: return to the ideas that need another look.')+`<div class="stats"><div class="stat"><b>${attempted.length}</b><span>Self-assessed</span></div><div class="stat"><b>${attempted.filter(id=>s.answers[id].rating==='got').length}</b><span>Got it</span></div><div class="stat"><b>${missed.length}</b><span>Need practice</span></div><div class="stat"><b>${ids.length-attempted.length}</b><span>Not yet assessed</span></div></div><div class="button-row" style="margin-bottom:25px">${button('Retry missed / partly →','retry','primary',missed.length?'':'disabled')}<a class="btn" href="#practice">New session</a><a class="btn" href="#review">View all progress</a></div><div class="question-list">${ids.map((id,i)=>{const q=qBy.get(id),slot=s.answers[id]||{},reached=slot.visited||slot.shown||slot.rating;return `<article class="question-row"><div class="row-top"><small>${q.courseIds.join(' + ')} · ${i+1}</small><span class="pill">${slot.rating||(!reached?'Not reached':slot.skipped?'Skipped':'Not assessed')}</span></div><p><strong>${esc(q.prompt)}</strong></p>${record(id).note?`<p class="muted">Your note: ${esc(record(id).note)}</p>`:''}<details><summary>Reveal answer & assess</summary>${answerHTML(q)}${ratingHTML(q,s,slot)}</details></article>`;}).join('')}</div>`);}
function questionPage(id){const q=qBy.get(id);if(!q){location.hash='review';return;}shell('review',`<div class="session-wrap"><a href="#review">← Review</a><article class="card question-card" style="margin-top:20px"><div class="inline-badges"><span class="pill">${q.courseIds.join(' + ')}</span><span class="pill">${q.difficulty}</span></div><h2>${esc(q.prompt)}</h2>${answerHTML(q)}<label class="field" style="margin-top:20px">Your note<textarea id="answer-note" data-qid="${id}">${esc(record(id).note)}</textarea></label><div class="button-row">${button('Practise this question','single-practice','primary',`data-id="${id}"`)}${button(record(id).bookmarked?'★ Saved':'☆ Save question','bookmark','',`data-id="${id}"`)}${button('Ask about this','question-guide','',`data-id="${id}"`)}</div></article></div>`);}
function review(){const list=db.questions.filter(q=>({weak:weak(p,q.id),past:past(p,q.id),bookmarked:!!p.questions[q.id]?.bookmarked,notes:!!p.questions[q.id]?.note,all:status(p,q.id)!=='unseen'}[reviewFilter]));shell('review',title('BUILD ON WHAT YOU KNOW','A second look helps.','Keep the tricky questions close. Your progress belongs to this browser.')+`<div class="tabs">${[['weak','Needs practice'],['past','Past mistakes'],['bookmarked','Bookmarks'],['notes','My notes'],['all','All attempted']].map(([v,l])=>button(l,'review-filter',reviewFilter===v?'active':'',`data-filter="${v}"`)).join('')}</div><div class="section-head"><span class="count-label">${list.length} questions</span>${button('Practise this list →','review-practice','small',list.length?'':'disabled')}</div><div class="question-list">${list.slice(0,150).map(q=>`<a class="question-row" href="#question/${q.id}"><div class="row-top"><small>${q.courseIds.join(' + ')} · ${esc(q.type)}</small><span class="pill">${status(p,q.id)}</span></div><p>${esc(q.prompt)}</p>${reviewFilter==='notes'?`<small>${esc(record(q.id).note.slice(0,180))}</small>`:''}</a>`).join('')||'<div class="card empty"><h2>A fresh page.</h2><p>Questions will appear here as you practise, save them, or add a note.</p><div class="button-row" style="justify-content:center"><a href="#practice" class="btn primary">Start a session →</a></div></div>'}</div>${list.length>150?'<p class="muted">Showing the first 150. Practise this list to sample from all matching questions.</p>':''}<section class="card" style="margin-top:30px"><h3>Keep a copy of your progress</h3><p class="muted" style="font-size:12px;margin-top:8px">Export a backup or move it to another browser. Import replaces this browser’s progress after confirmation. Clearing site data removes the local copy.</p><div class="button-row">${button('Export progress','export')}${button('Import progress','import')}<input type="file" id="import-file" accept="application/json,.json" hidden></div></section>`);}
function coverage(){shell('study',title('CONTENT & SOURCES','Know what you are covering.','Every syllabus item is mapped to a lesson and its practice questions. Page references refer to the supplied PDFs, not unseen original textbooks.')+`<div class="card"><p>${db.questions.length} questions · ${db.topics.length} topics · ${db.questions.filter(q=>q.essential).length} essentials · ${db.questions.filter(q=>q.courseIds.length>1).length} cross-course questions</p><div class="button-row"><a class="btn" href="data/coverage.json" download>Download coverage map</a><a class="btn" href="data/library.json" download>Download study content</a></div></div>${db.courses.map(c=>`<section class="card" style="margin-top:20px"><h2>${c.id} · ${esc(c.shortTitle)}</h2><table class="coverage-table"><thead><tr><th>Syllabus area</th><th>Topics & practice</th></tr></thead><tbody>${c.groups.map(g=>`<tr><td><strong>${esc(g.title)}</strong><p>${esc(g.syllabus.join('; '))}</p></td><td>${c.topics.filter(t=>t.groupId===g.id).map(t=>`<a href="#study/${c.id}/${t.id}">${esc(t.title)} (${t.questions.length})</a>`).join('<br>')}</td></tr>`).join('')}</tbody></table></section>`).join('')}<section class="card" style="margin-top:20px"><h2>How this guide was prepared</h2><p style="margin-top:15px">The supplied course summaries define the main reading base. Academic supplements fill identified syllabus gaps and qualify misleading simplifications. Examples are teaching illustrations unless explicitly described otherwise. Difficulty and essentials are preparation choices, not predictions of exam questions.</p><p>Self-ratings describe your own assessment, not an examiner’s grade. The original PDF files are not republished here.</p></section>`);}
function route(){clearInterval(timer);const [page='home',id,topic]=location.hash.slice(1).split('/');if(page==='home')home();else if(page==='study')study(id,topic);else if(page==='practice')setup();else if(page==='session')session();else if(page==='review')review();else if(page==='question')questionPage(id);else if(page==='coverage')coverage();else home();}
function go(hash){if(location.hash==='#'+hash)route();else location.hash=hash;}
function start(ids,kind='drill'){if(!ids.length){toast('No questions match. Broaden your filters.');return;}if(p.session?.state==='active'&&!confirm('Replace the unfinished session? Your ratings and notes will stay saved.'))return;p.session={id:(globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2)),kind,ids,index:0,startedAt:Date.now(),deadline:kind==='mock'?Date.now()+(filters.minutes||10)*60000:null,state:'active',answers:{[ids[0]]:{visited:true}}};persist();go('session');}
function finish(){if(p.session){p.session.state='complete';p.session.finishedAt=Date.now();persist();}clearInterval(timer);go('session');}
function tick(){const update=()=>{const s=p.session;if(!s||s.state!=='active')return;const left=Math.max(0,Math.ceil((s.deadline-Date.now())/1000));const el=$('#timer');if(el)el.textContent=`${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}`;if(!left)finish();};update();timer=setInterval(update,1000);}
function modalOpen(html){modal.innerHTML=html;if(!modal.open)modal.showModal();}
const modalHead=t=>`<div class="modal-head"><h2>${t}</h2><button data-action="close" aria-label="Close dialog">×</button></div>`;
function openSearch(value=''){modalOpen(modalHead('A question, a concept, a connection.')+`<label class="field">Search your study library<input class="search-input" id="search-query" placeholder="Try allomorph, face, or interlanguage…" value="${esc(value)}"></label><div class="search-results" id="search-results"></div>`);$('#search-query').focus();search(value);}
function search(value){const terms=normalize(value).split(' ').filter(Boolean);const el=$('#search-results');if(!terms.length){el.innerHTML='<p class="muted">Search across all seven courses. This search works without AI.</p>';return;}const topics=db.topics.filter(t=>terms.every(x=>normalize(t.title+' '+(t.aliases||[]).join(' ')+' '+t.core).includes(x)));const qs=db.questions.filter(q=>terms.every(x=>normalize(q.prompt+' '+q.answer).includes(x)));el.innerHTML=`<small>${topics.length} topics · ${qs.length} questions</small>`+topics.slice(0,12).map(t=>`<a data-action="close-link" href="#study/${t.courseId}/${t.id}"><small>${t.courseId} · Topic</small><h3>${esc(t.title)}</h3><p class="muted">${esc(t.core)}</p></a>`).join('')+qs.slice(0,35).map(q=>`<a data-action="close-link" href="#question/${q.id}"><small>${q.courseIds.join(' + ')} · Question</small><p>${esc(q.prompt)}</p></a>`).join('')+(!topics.length&&!qs.length?'<p class="empty">No matches yet. Try a shorter term or another spelling.</p>':'');}
function markdown(text){if(globalThis.marked&&globalThis.DOMPurify)return DOMPurify.sanitize(marked.parse(text,{gfm:true,breaks:true}));return '<p>'+esc(text).replace(/\n/g,'<br>')+'</p>';}
function openGuide(context=chatContext){chatContext=context;const selected=context.courseIds?.[0]||'';modalOpen(modalHead('AI Viva Tutor')+`<p class="muted">Ask in English, Bangla or Banglish. Or search the built-in question bank.</p><div id="chat-messages" aria-live="polite">${chat.map((m,i)=>`<article class="chat-message ${m.role}"><small>${m.role==='user'?'You':'AI Tutor'}</small><div class="${m.role==='assistant'?'ai-markdown':''}">${m.role==='assistant'?markdown(m.content):esc(m.content)}</div>${m.role==='assistant'?`<button class="btn small" data-action="copy-answer" data-index="${i}">Copy Answer</button>`:''}</article>`).join('')}</div><form id="chat-form" class="chat-form"><label class="field">Course (optional)<select id="chat-course"><option value="">All courses</option>${db.courses.map(c=>`<option value="${c.id}" ${selected===c.id?'selected':''}>${c.id} · ${esc(c.shortTitle)}</option>`).join('')}</select></label><label class="field">Your question<textarea id="chat-input" placeholder="Ask anything about your viva materials…"></textarea></label><p id="chat-error" role="alert"></p><div class="button-row"><button class="btn primary" type="submit">Ask AI Tutor</button><button type="button" class="btn" data-action="guide-search">Search question bank</button></div></form>`);}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;const s=p?.session,qid=s?.ids[s.index];if(a==='search')openSearch();else if(a==='guide')openGuide();else if(a==='topic-guide')openGuide({courseIds:[tBy.get(id).courseId],topicIds:[id]});else if(a==='question-guide')openGuide({courseIds:qBy.get(id).courseIds,topicIds:qBy.get(id).topicIds,questionId:id});else if(a==='close'||a==='close-link')modal.close();else if(a==='guide-search'){const text=$('#chat-input').value;openSearch(text);}else if(a==='resume')go('session');else if(a==='essentials'||a==='course-essentials'){filters={courses:id?[id]:[],essential:true,mode:'mixed',count:20};go('practice');}else if(a==='course-practice'||a==='topic-practice'){filters={courses:a==='course-practice'?[id]:[tBy.get(id).courseId],topic:a==='topic-practice'?id:'',mode:'drill',count:20};go('practice');}else if(a==='connections'||a==='mock'){filters={courses:[],mode:a,connections:a==='connections',count:20};go('practice');}else if(a==='mode'){filters.mode=el.dataset.mode;filters.connections=filters.mode==='connections';if(filters.mode==='all'){filters={courses:[],mode:'all',count:790};}setup();}else if(a==='all-courses'){filters.courses=[];setup();}else if(a==='start')start(filters.mode==='mock'?mockQueue(db.questions,filters,p):queue(db.questions,filters,p),filters.mode==='mock'?'mock':'drill');else if(a==='copy-answer'){navigator.clipboard.writeText(chat[Number(el.dataset.index)].content).then(()=>toast('Answer copied')).catch(()=>toast('Copy unavailable. Select the answer text to copy.'));}else if(a==='previous'){s.index=Math.max(0,s.index-1);persist();session();}else if(a==='single-practice')start([id]);else if(a==='bookmark'){record(id).bookmarked=!record(id).bookmarked;record(id).updatedAt=Date.now();persist();el.textContent=record(id).bookmarked?'★ Saved':'☆ Save question';}else if(a==='reveal'||a==='dontknow'){const slot=s.answers[qid]??={};slot.shown=true;if(a==='dontknow'){slot.rating='missed';rate(p,qid,'missed',s.id+'/'+qid);}persist();session();}else if(a==='rate'){const slot=s.answers[id]??={};slot.rating=el.dataset.rating;rate(p,id,el.dataset.rating,s.id+'/'+id);persist();el.parentElement.querySelectorAll('button').forEach(b=>{b.classList.toggle('selected',b===el);b.setAttribute('aria-pressed',b===el?'true':'false');});toast('Assessment saved');if(s.state==='complete'){const open=[...document.querySelectorAll('details')].map((x,i)=>x.open?i:-1);results();document.querySelectorAll('details').forEach((x,i)=>x.open=open.includes(i));}}else if(a==='next'||a==='skip'){const slot=s.answers[qid]??={};slot.visited=true;if(a==='skip')slot.skipped=true;s.index++;if(s.index>=s.ids.length)finish();else{s.answers[s.ids[s.index]]??={visited:true};persist();session();}}else if(a==='finish')finish();else if(a==='retry')start(s.ids.filter(id=>['missed','partly'].includes(s.answers[id]?.rating)));else if(a==='review-filter'){reviewFilter=el.dataset.filter;review();}else if(a==='review-practice'){let ids=db.questions.filter(q=>({weak:weak(p,q.id),past:past(p,q.id),bookmarked:record(q.id).bookmarked,notes:!!record(q.id).note,all:status(p,q.id)!=='unseen'}[reviewFilter])).map(q=>q.id);start(ids.slice(0,30));}else if(a==='export'){const u=URL.createObjectURL(new Blob([JSON.stringify(p,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=u;link.download='viva-studio-progress.json';link.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}else if(a==='import')$('#import-file').click();});
document.addEventListener('input',e=>{if(e.target.id==='answer-note'){const r=record(e.target.dataset.qid);r.note=e.target.value;r.updatedAt=Date.now();persist();}if(e.target.id==='search-query'){clearTimeout(searchTimer);searchTimer=setTimeout(()=>search(e.target.value),120);}});
document.addEventListener('change',async e=>{const el=e.target;if(el.name==='course'){const selected=[...document.querySelectorAll('input[name="course"]:checked')].map(x=>x.value);filters.courses=selected.length?selected:['none'];filters.topic='';setup();}else if(el.dataset.filter){const key=el.dataset.filter;filters[key]=el.type==='checkbox'?el.checked:['count','minutes'].includes(key)?Number(el.value):el.value;setup();}else if(el.id==='import-file'){try{const file=el.files[0];if(!file)return;if(file.size>10000000)throw Error('The progress file is too large.');const next=parseProgress(await file.text(),new Set(qBy.keys()));if(confirm('Replace this browser’s progress with the imported file? Export first if you want to keep both.')){p=next;persist();route();toast('Progress imported');}}catch(err){toast(err.message);}el.value='';}});
document.addEventListener('submit',async e=>{if(e.target.id!=='chat-form')return;e.preventDefault();const input=$('#chat-input'),message=input.value.trim(),course=$('#chat-course').value;if(!message||e.target.dataset.busy)return;e.target.dataset.busy='true';chatContext={courseIds:course?[course]:[]};const btn=e.target.querySelector('[type="submit"]');btn.disabled=true;btn.classList.add('generating');btn.textContent='Generating viva-ready answer…';$('#chat-error').textContent='';chat.push({role:'user',content:message});try{const result=await sendGuideMessage({question:message,course});chat.push({role:'assistant',content:result.answer});if(modal.open){openGuide(chatContext);$('#chat-messages').lastElementChild?.scrollIntoView({block:'nearest'});}}catch(err){chat.pop();if($('#chat-error'))$('#chat-error').textContent=err.message;if(btn.isConnected){btn.disabled=false;btn.classList.remove('generating');btn.textContent='Ask AI Tutor';e.target.dataset.busy='';}}});
window.addEventListener('hashchange',()=>{route();window.scrollTo(0,0);});window.addEventListener('storage',e=>{if(e.key===KEY){const next=readProgress(storage,new Set(qBy.keys()));if(next.available){p=next.data;route();}}});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!modal.open){e.preventDefault();openSearch();}});
try{const response=await fetch('data/library.json');if(!response.ok)throw Error('The study library could not load. Please refresh.');db=await response.json();db.questions.forEach(q=>qBy.set(q.id,q));db.topics.forEach(t=>tBy.set(t.id,t));db.courses.forEach(c=>cBy.set(c.id,c));try{storage=window.localStorage;}catch{storage=null;}const loaded=readProgress(storage,new Set(qBy.keys()));p=loaded.data;storageOk=loaded.available;route();}catch(err){app.innerHTML=`<main class="loading"><h1>Let’s try that again.</h1><p>${esc(err.message)}</p><button class="btn" onclick="location.reload()">Reload</button></main>`;}
